// components/professor/QuizCreation.jsx
import React, { useState } from 'react';
import { useNavigate } from 'react-router-dom';

const QuizCreation = () => {
  const navigate = useNavigate();
  const [currentStep, setCurrentStep] = useState(1);
  const [quiz, setQuiz] = useState({
    title: '',
    description: '',
    timeLimit: 30,
    isPublic: true,
    questions: []
  });
  
  const [currentQuestion, setCurrentQuestion] = useState({
    text: '',
    type: 'multiple_choice',
    points: 1,
    options: [
      { text: '', isCorrect: false },
      { text: '', isCorrect: false },
      { text: '', isCorrect: false },
      { text: '', isCorrect: false }
    ]
  });
  
  // Handle quiz information changes
  const handleQuizChange = (e) => {
    const { name, value, type, checked } = e.target;
    setQuiz({
      ...quiz,
      [name]: type === 'checkbox' ? checked : value
    });
  };
  
  // Handle current question changes
  const handleQuestionChange = (e) => {
    const { name, value } = e.target;
    setCurrentQuestion({
      ...currentQuestion,
      [name]: value
    });
  };
  
  // Handle option changes
  const handleOptionChange = (index, e) => {
    const { name, value, type, checked } = e.target;
    const updatedOptions = [...currentQuestion.options];
    
    if (type === 'checkbox') {
      // For multiple choice, only one can be correct
      if (currentQuestion.type === 'multiple_choice' && checked) {
        updatedOptions.forEach(option => option.isCorrect = false);
      }
      updatedOptions[index] = {
        ...updatedOptions[index],
        isCorrect: checked
      };
    } else {
      updatedOptions[index] = {
        ...updatedOptions[index],
        [name]: value
      };
    }
    
    setCurrentQuestion({
      ...currentQuestion,
      options: updatedOptions
    });
  };
  
  // Add option to current question
  const addOption = () => {
    if (currentQuestion.options.length < 8) {
      setCurrentQuestion({
        ...currentQuestion,
        options: [
          ...currentQuestion.options,
          { text: '', isCorrect: false }
        ]
      });
    }
  };
  
  // Remove option from current question
  const removeOption = (index) => {
    if (currentQuestion.options.length > 2) {
      const updatedOptions = currentQuestion.options.filter((_, i) => i !== index);
      setCurrentQuestion({
        ...currentQuestion,
        options: updatedOptions
      });
    }
  };
  
  // Add current question to quiz
  const addQuestion = () => {
    // Validate question first
    let valid = currentQuestion.text.trim() !== '';
    let hasCorrectAnswer = currentQuestion.options.some(option => option.isCorrect);
    
    if (!valid || !hasCorrectAnswer) {
      alert('Veuillez compléter la question et marquer au moins une réponse comme correcte.');
      return;
    }
    
    setQuiz({
      ...quiz,
      questions: [...quiz.questions, { ...currentQuestion, id: Date.now() }]
    });
    
    // Reset current question
    setCurrentQuestion({
      text: '',
      type: 'multiple_choice',
      points: 1,
      options: [
        { text: '', isCorrect: false },
        { text: '', isCorrect: false },
        { text: '', isCorrect: false },
        { text: '', isCorrect: false }
      ]
    });
  };
  
  // Edit existing question
  const editQuestion = (index) => {
    setCurrentQuestion(quiz.questions[index]);
    // Remove the question from the list
    const updatedQuestions = quiz.questions.filter((_, i) => i !== index);
    setQuiz({
      ...quiz,
      questions: updatedQuestions
    });
  };
  
  // Remove question from quiz
  const removeQuestion = (index) => {
    const updatedQuestions = quiz.questions.filter((_, i) => i !== index);
    setQuiz({
      ...quiz,
      questions: updatedQuestions
    });
  };
  
  // Navigate to next step
  const nextStep = () => {
    if (currentStep === 1) {
      // Validate quiz info
      if (!quiz.title.trim()) {
        alert('Veuillez donner un titre à votre quiz.');
        return;
      }
    }
    setCurrentStep(currentStep + 1);
  };
  
  // Navigate to previous step
  const prevStep = () => {
    setCurrentStep(currentStep - 1);
  };
  
  // Save quiz
  const saveQuiz = () => {
    // This would be an API call in a real application
    console.log('Quiz saved:', quiz);
    
    // Mock saving process
    setTimeout(() => {
      alert('Quiz créé avec succès!');
      navigate('/professor/manage-quiz');
    }, 1000);
  };
  
  return (
    <div className="content-area w-full max-w-6xl mx-auto px-4 py-6"> {/* max-w-6xl pour une largeur plus grande */}
      <h1 className="text-2xl font-bold mb-6">Créer un Nouveau Quiz</h1>
      
      {/* Step indicator */}
      <div className="stepper flex justify-between mb-8">
        <div className={`step flex flex-col items-center flex-1 ${currentStep >= 1 ? 'active' : ''}`}>
          <div className="step-number w-8 h-8 rounded-full bg-blue-500 text-white flex items-center justify-center">1</div>
          <div className="step-label mt-2 text-sm">Informations du Quiz</div>
        </div>
        <div className="step-connector flex-1 h-0.5 bg-gray-300 self-center mx-2"></div>
        <div className={`step flex flex-col items-center flex-1 ${currentStep >= 2 ? 'active' : ''}`}>
          <div className="step-number w-8 h-8 rounded-full bg-gray-300 text-gray-700 flex items-center justify-center">2</div>
          <div className="step-label mt-2 text-sm">Ajouter des Questions</div>
        </div>
        <div className="step-connector flex-1 h-0.5 bg-gray-300 self-center mx-2"></div>
        <div className={`step flex flex-col items-center flex-1 ${currentStep >= 3 ? 'active' : ''}`}>
          <div className="step-number w-8 h-8 rounded-full bg-gray-300 text-gray-700 flex items-center justify-center">3</div>
          <div className="step-label mt-2 text-sm">Récapitulatif</div>
        </div>
      </div>
      
      {/* Step 1: Quiz Information */}
      {currentStep === 1 && (
        <div className="quiz-info bg-white p-6 rounded-lg shadow-md">
          <div className="form-group mb-4">
            <label htmlFor="title" className="block text-sm font-medium mb-1">Titre du Quiz</label>
            <input
              type="text"
              id="title"
              name="title"
              value={quiz.title}
              onChange={handleQuizChange}
              placeholder="Entrez le titre du quiz"
              className="w-full p-2 border border-gray-300 rounded"
              required
            />
          </div>
          
          <div className="form-group mb-4">
            <label htmlFor="description" className="block text-sm font-medium mb-1">Description</label>
            <textarea
              id="description"
              name="description"
              value={quiz.description}
              onChange={handleQuizChange}
              placeholder="Entrez une description pour votre quiz"
              rows="4"
              className="w-full p-2 border border-gray-300 rounded"
            ></textarea>
          </div>
          
          <div className="form-group mb-4">
            <label htmlFor="timeLimit" className="block text-sm font-medium mb-1">Temps limite (en minutes)</label>
            <input
              type="number"
              id="timeLimit"
              name="timeLimit"
              value={quiz.timeLimit}
              onChange={handleQuizChange}
              min="1"
              max="180"
              className="w-full p-2 border border-gray-300 rounded"
            />
          </div>
          
          <div className="form-group mb-6">
            <label className="flex items-center text-sm font-medium">
              <input
                type="checkbox"
                name="isPublic"
                checked={quiz.isPublic}
                onChange={handleQuizChange}
                className="mr-2"
              />
              Rendre ce quiz public pour tous les étudiants
            </label>
          </div>
          
          <div className="form-actions flex justify-end">
            <button 
              className="btn btn-primary bg-blue-500 text-white py-2 px-4 rounded hover:bg-blue-600" 
              onClick={nextStep}
            >
              Continuer
            </button>
          </div>
        </div>
      )}
      
      {/* Step 2: Add Questions */}
      {currentStep === 2 && (
        <div className="quiz-questions grid grid-cols-1 gap-6">
          <div className="question-form bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-xl font-medium mb-4">Ajouter une Question</h2>
            
            <div className="form-group mb-4">
              <label htmlFor="questionText" className="block text-sm font-medium mb-1">Question</label>
              <textarea
                id="questionText"
                name="text"
                value={currentQuestion.text}
                onChange={handleQuestionChange}
                placeholder="Entrez votre question"
                rows="2"
                className="w-full p-2 border border-gray-300 rounded"
                required
              ></textarea>
            </div>
            
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-4">
              <div className="form-group">
                <label htmlFor="questionType" className="block text-sm font-medium mb-1">Type de Question</label>
                <select
                  id="questionType"
                  name="type"
                  value={currentQuestion.type}
                  onChange={handleQuestionChange}
                  className="w-full p-2 border border-gray-300 rounded"
                >
                  <option value="multiple_choice">Choix Multiple (une réponse)</option>
                  <option value="checkbox">Cases à Cocher (plusieurs réponses)</option>
                </select>
              </div>
              
              <div className="form-group">
                <label htmlFor="points" className="block text-sm font-medium mb-1">Points</label>
                <input
                  type="number"
                  id="points"
                  name="points"
                  value={currentQuestion.points}
                  onChange={handleQuestionChange}
                  min="1"
                  max="10"
                  className="w-full p-2 border border-gray-300 rounded"
                />
              </div>
            </div>
            
            <h3 className="text-lg font-medium mb-3">Options</h3>
            {currentQuestion.options.map((option, index) => (
              <div className="option-row flex items-center mb-3" key={index}>
                <div className="form-group flex-grow mr-3">
                  <input
                    type="text"
                    name="text"
                    value={option.text}
                    onChange={(e) => handleOptionChange(index, e)}
                    placeholder={`Option ${index + 1}`}
                    className="w-full p-2 border border-gray-300 rounded"
                    required
                  />
                </div>
                
                <div className="form-group flex items-center mr-3">
                  <label className="flex items-center text-sm">
                    <input
                      type={currentQuestion.type === 'multiple_choice' ? 'radio' : 'checkbox'}
                      name="isCorrect"
                      checked={option.isCorrect}
                      onChange={(e) => handleOptionChange(index, e)}
                      className="mr-1"
                    />
                    Correcte
                  </label>
                </div>
                
                <button 
                  type="button" 
                  className="btn btn-danger bg-red-500 text-white p-2 rounded hover:bg-red-600" 
                  onClick={() => removeOption(index)}
                  disabled={currentQuestion.options.length <= 2}
                >
                  <span className="sr-only">Supprimer</span>
                  ✕
                </button>
              </div>
            ))}
            
            <div className="form-group mb-4">
              <button 
                type="button" 
                className="btn btn-secondary bg-gray-200 text-gray-700 py-1 px-3 rounded hover:bg-gray-300" 
                onClick={addOption}
                disabled={currentQuestion.options.length >= 8}
              >
                + Ajouter une option
              </button>
            </div>
            
            <div className="form-actions">
              <button 
                type="button" 
                className="btn btn-success bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600" 
                onClick={addQuestion}
              >
                Ajouter la Question
              </button>
            </div>
          </div>
          
          <div className="questions-list bg-white p-6 rounded-lg shadow-md">
            <h2 className="text-xl font-medium mb-4">Questions ({quiz.questions.length})</h2>
            {quiz.questions.length === 0 ? (
              <p className="text-gray-500">Aucune question ajoutée. Ajoutez au moins une question.</p>
            ) : (
              <div className="question-cards grid grid-cols-1 gap-4">
                {quiz.questions.map((question, index) => (
                  <div className="card border border-gray-200 rounded-lg" key={index}>
                    <div className="card-header bg-gray-50 p-4 flex justify-between items-center rounded-t-lg">
                      <h3 className="card-title text-lg font-medium">Question {index + 1}</h3>
                      <div className="card-actions flex space-x-2">
                        <button 
                          className="btn btn-secondary bg-gray-200 text-gray-700 py-1 px-3 rounded hover:bg-gray-300" 
                          onClick={() => editQuestion(index)}
                        >
                          Éditer
                        </button>
                        <button 
                          className="btn btn-danger bg-red-500 text-white py-1 px-3 rounded hover:bg-red-600" 
                          onClick={() => removeQuestion(index)}
                        >
                          Supprimer
                        </button>
                      </div>
                    </div>
                    <div className="card-content p-4">
                      <p className="mb-3">{question.text}</p>
                      <div className="options-list mb-3">
                        <strong>Options:</strong>
                        <ul className="list-disc pl-6 mt-1">
                          {question.options.map((option, optIndex) => (
                            <li key={optIndex} className={option.isCorrect ? 'text-green-600 font-medium' : ''}>
                              {option.text} {option.isCorrect && '✓'}
                            </li>
                          ))}
                        </ul>
                      </div>
                      <div className="question-meta text-sm text-gray-600 flex justify-between">
                        <span>Type: {question.type === 'multiple_choice' ? 'Choix Multiple' : 'Cases à Cocher'}</span>
                        <span>Points: {question.points}</span>
                      </div>
                    </div>
                  </div>
                ))}
              </div>
            )}
          </div>
          
          <div className="form-actions flex justify-between mt-4">
            <button 
              className="btn btn-secondary bg-gray-200 text-gray-700 py-2 px-4 rounded hover:bg-gray-300" 
              onClick={prevStep}
            >
              Retour
            </button>
            <button 
              className="btn btn-primary bg-blue-500 text-white py-2 px-4 rounded hover:bg-blue-600" 
              onClick={nextStep}
              disabled={quiz.questions.length === 0}
            >
              Continuer
            </button>
          </div>
        </div>
      )}
      
      {/* Step 3: Quiz Summary */}
      {currentStep === 3 && (
        <div className="quiz-summary">
          <h2 className="text-xl font-medium mb-4">Récapitulatif du Quiz</h2>
          
          <div className="card border border-gray-200 rounded-lg mb-6">
            <div className="card-header bg-gray-50 p-4 rounded-t-lg">
              <h3 className="card-title text-lg font-medium">Informations Générales</h3>
            </div>
            <div className="card-content p-4">
              <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                <div>
                  <p className="mb-2"><strong>Titre:</strong> {quiz.title}</p>
                  <p className="mb-2"><strong>Description:</strong> {quiz.description || 'Aucune description'}</p>
                  <p className="mb-2"><strong>Temps Limite:</strong> {quiz.timeLimit} minutes</p>
                </div>
                <div>
                  <p className="mb-2"><strong>Statut:</strong> {quiz.isPublic ? 'Public' : 'Privé'}</p>
                  <p className="mb-2"><strong>Nombre de Questions:</strong> {quiz.questions.length}</p>
                  <p className="mb-2"><strong>Points Totaux:</strong> {quiz.questions.reduce((sum, q) => sum + parseInt(q.points), 0)}</p>
                </div>
              </div>
            </div>
          </div>
          
          <h3 className="text-lg font-medium mb-3">Questions ({quiz.questions.length})</h3>
          <div className="accordion">
            {quiz.questions.map((question, index) => (
              <div className="accordion-item border border-gray-200 rounded-lg mb-3" key={index}>
                <div className="accordion-header bg-gray-50 p-4 rounded-t-lg">
                  <h4 className="font-medium">Question {index + 1}: {question.text.slice(0, 50)}{question.text.length > 50 ? '...' : ''}</h4>
                </div>
                <div className="accordion-content p-4">
                  <p className="mb-2"><strong>Question:</strong> {question.text}</p>
                  <p className="mb-2"><strong>Type:</strong> {question.type === 'multiple_choice' ? 'Choix Multiple' : 'Cases à Cocher'}</p>
                  <p className="mb-2"><strong>Points:</strong> {question.points}</p>
                  <div className="options-list">
                    <strong>Options:</strong>
                    <ul className="list-disc pl-6 mt-1">
                      {question.options.map((option, optIndex) => (
                        <li key={optIndex} className={option.isCorrect ? 'text-green-600 font-medium' : ''}>
                          {option.text} {option.isCorrect && '✓'}
                        </li>
                      ))}
                    </ul>
                  </div>
                </div>
              </div>
            ))}
          </div>
          
          <div className="form-actions mt-6 flex justify-end space-x-3">
            <button 
              className="btn btn-secondary bg-gray-200 text-gray-700 py-2 px-4 rounded hover:bg-gray-300" 
              onClick={prevStep}
            >
              Retour
            </button>
            <button 
              className="btn btn-success bg-green-500 text-white py-2 px-4 rounded hover:bg-green-600" 
              onClick={saveQuiz}
            >
              Créer le Quiz
            </button>
          </div>
        </div>
      )}
    </div>
  );
};

export default QuizCreation;
